const ACTOR='actor-field', QUEUE='vigia.field.queue.v3';
const root=document.querySelector('[data-assignments]'), dialog=document.querySelector('[data-dialog]'), form=document.querySelector('[data-form]'), network=document.querySelector('[data-network]'), syncButton=document.querySelector('[data-sync]'), themeButton=document.querySelector('[data-theme-toggle]'), toast=document.querySelector('[data-toast]');
let assignments=[], active=null, position=null;
const queued=()=>JSON.parse(localStorage.getItem(QUEUE)||'[]');
const saveQueue=(items)=>{localStorage.setItem(QUEUE,JSON.stringify(items));syncButton.textContent=`Sync ${items.length}`};
function show(message){toast.textContent=message;toast.hidden=false;setTimeout(()=>toast.hidden=true,2800)}
async function api(path,options={}){const response=await fetch(path,{...options,headers:{'x-vigia-actor-id':ACTOR,...(options.body?{'content-type':'application/json'}:{})},body:options.body&&typeof options.body!=='string'?JSON.stringify(options.body):options.body});if(!response.ok)throw new Error((await response.json().catch(()=>({}))).message||`request_${response.status}`);return response.json()}
function render(){root.innerHTML=assignments.map((item)=>`<article class="card"><header><span>${item.kind==='request'?'EVIDENCE REQUEST':'REMEDIATION'} · ${item.state.replaceAll('_',' ')}</span></header><h2>${item.title}</h2><p>${item.kind==='request'?(item.requirements||[]).join(' · '):item.recommendation||'Completion evidence required.'}</p><div class="meta"><p>Due ${new Date(item.dueAt).toLocaleString()}</p></div><button type="button" data-open="${item.id}" data-kind="${item.kind}">${item.kind==='request'?'Capture evidence':'Capture completion proof'}</button></article>`).join('')||'<p>No active assignments.</p>'}
async function load(){try{const data=await api('/api/v2/field');assignments=[...data.requests.map(i=>({...i,kind:'request'})),...data.remediations.map(i=>({...i,kind:'remediation'}))];render()}catch(error){show(error.message)}}
function getGps(){return new Promise((resolve,reject)=>navigator.geolocation?.getCurrentPosition(resolve,reject,{enableHighAccuracy:true,timeout:10000,maximumAge:30000})||reject(new Error('geolocation_unavailable')))}
function compress(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>{const image=new Image();image.onerror=reject;image.onload=()=>{const max=640,scale=Math.min(1,max/image.width),canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.68))};image.src=reader.result};reader.readAsDataURL(file)})}
async function openCapture(item){active=item;try{const result=await getGps();position={coordinate:[result.coords.longitude,result.coords.latitude],accuracy:Math.round(result.coords.accuracy),locationSource:'device_gps'}}catch{position={coordinate:item.coordinate,accuracy:null,locationSource:'assignment_coordinate'};show('GPS unavailable; location is explicitly assignment-derived and cannot automatically resolve the event.')}form.elements.gps.value=position.coordinate?.join(', ')||'Unavailable';form.elements.accuracy.value=position.accuracy??'Unavailable · assignment coordinate';form.querySelector('[data-title]').textContent=item.title;dialog.showModal();form.elements.note.focus()}
async function submit(event){event.preventDefault();const data=new FormData(form),file=form.elements.photo.files[0],image=file?await compress(file):'';const payload={capturedAt:new Date().toISOString(),coordinate:position.coordinate,accuracyMeters:position.accuracy,note:data.get('note'),observations:String(data.get('observations')).split(/\n/).filter(Boolean),attachments:[{id:`field:${Date.now()}`,type:'image',name:file?.name||'field.jpg',url:image,size:file?.size||0}],provenance:{device:navigator.userAgent,clientVersion:'10.0.0',offlineCaptured:!navigator.onLine,source:'field-capture',locationSource:position.locationSource}};const operations=[];if(active.kind==='request'){if(active.state==='requested')operations.push({clientId:crypto.randomUUID(),type:'acknowledge',requestId:active.id,payload:{note:'Accepted in field capture'}});if(['requested','acknowledged'].includes(active.state))operations.push({clientId:crypto.randomUUID(),type:'start',requestId:active.id,payload:{note:'Evidence capture started'}});operations.push({clientId:crypto.randomUUID(),type:'submit_evidence',requestId:active.id,payload})}else operations.push({clientId:crypto.randomUUID(),type:'completion',remediationId:active.id,payload});saveQueue([...queued(),...operations]);dialog.close();form.reset();show('Evidence saved to the offline queue.');if(navigator.onLine)await sync()}
async function sync(){const operations=queued();if(!operations.length)return show('Nothing to sync.');const remaining=[],evidenceOps=operations.filter(o=>o.type!=='completion'),completionOps=operations.filter(o=>o.type==='completion');try{if(evidenceOps.length){const result=await api('/api/v2/field/sync',{method:'POST',body:{operations:evidenceOps}});for(const item of result.results)if(!item.ok)remaining.push(evidenceOps.find(o=>o.clientId===item.clientId))}for(const op of completionOps){try{await api(`/api/v2/remediations/${encodeURIComponent(op.remediationId)}/completion`,{method:'POST',body:op.payload})}catch{remaining.push(op)}}saveQueue(remaining.filter(Boolean));show(remaining.length?'Some evidence remains queued.':'Field evidence synced.');await load()}catch(error){show(`Sync deferred: ${error.message}`)}}
document.addEventListener('click',e=>{const button=e.target.closest('[data-open]');if(button)openCapture(assignments.find(i=>i.id===button.dataset.open));if(e.target.closest('[data-close]')){e.preventDefault();dialog.close()}});dialog.addEventListener('cancel',e=>{e.preventDefault();dialog.close()});form.addEventListener('submit',submit);syncButton.addEventListener('click',sync);window.addEventListener('online',()=>{network.textContent='Online';sync()});window.addEventListener('offline',()=>network.textContent='Offline · evidence will queue');network.textContent=navigator.onLine?'Online':'Offline · evidence will queue';saveQueue(queued());navigator.serviceWorker?.register('/field/sw.js');load();

function setTheme(theme){document.body.dataset.theme=theme;localStorage.setItem('vigia.field.theme',theme);themeButton.textContent=theme==='daylight'?'Night':'Daylight'}
themeButton.addEventListener('click',()=>setTheme(document.body.dataset.theme==='daylight'?'night':'daylight'));
setTheme(localStorage.getItem('vigia.field.theme')||((matchMedia('(prefers-color-scheme: light)').matches)?'daylight':'night'));
